"""
Correctness checking: uses whatever's been recorded for an executable
literally named `jlox` as the ground truth for every "correctness check"
entry (see semantics.py), and flags any run whose check values disagree
with it.
"""

from pathlib import Path

from semantics import is_check_entry


def _is_jlox(executable_path):
    return Path(executable_path).name.lower() == "jlox"


def build_jlox_reference(history):
    """Returns {benchmark: {index: value}} from the most recently recorded
    run of an executable named 'jlox'. Returns {} if none has been recorded
    yet, in which case correctness checking simply can't happen."""
    jlox_runs = [r for r in history["runs"] if _is_jlox(r["executable"])]
    if not jlox_runs:
        return {}
    run = jlox_runs[-1]
    reference = {}
    for bench, block in run["benchmarks"].items():
        if block["error"]:
            continue
        reference[bench] = {i: e["value"] for i, e in enumerate(block["entries"])}
    return reference


def find_correctness_errors(history, reference=None, run_ids=None):
    """Returns a list of dicts describing every correctness-check entry that
    disagrees with the jlox reference:
        {run_id, executable, benchmark, index, label, expected, actual}

    If run_ids is given, only checks runs with those ids (still using the
    reference built from the *whole* history, so a subset view like "just
    the run I just recorded" is still checked against the full picture).
    """
    if reference is None:
        reference = build_jlox_reference(history)
    errors = []
    if not reference:
        return errors

    for run in history["runs"]:
        if run_ids is not None and run["id"] not in run_ids:
            continue
        for bench, block in run["benchmarks"].items():
            if block["error"]:
                continue
            ref_vals = reference.get(bench)
            if not ref_vals:
                continue
            for i, entry in enumerate(block["entries"]):
                if not is_check_entry(bench, i, entry["label"]):
                    continue
                expected = ref_vals.get(i)
                if expected is None:
                    continue
                actual = entry["value"]
                tolerance = max(1e-9, abs(expected) * 1e-9)
                if abs(actual - expected) > tolerance:
                    errors.append({
                        "run_id": run["id"],
                        "executable": run["executable"],
                        "benchmark": bench,
                        "index": i,
                        "label": entry["label"] or f"#{i}",
                        "expected": expected,
                        "actual": actual,
                    })
    return errors


def format_mismatch(e):
    """Formats an error dict from find_correctness_errors() with enough
    precision that "expected" and "got" never look identical when they
    aren't. A low-precision format like `.6g` can round two genuinely
    different values (e.g. 10000000 vs 10000002) to the same displayed
    text, which reads as a bug in the tool rather than a real mismatch --
    this always shows the exact values and their difference instead."""
    expected, actual = e["expected"], e["actual"]
    diff = actual - expected
    return (f"expected {expected!r}, got {actual!r} "
            f"(differs by {diff!r})")
